MANIFEST="app/src/main/AndroidManifest.xml"
if ! grep -q "LxArtistDetailActivity" "$MANIFEST"; then
    python3 << 'PYEOF2'
manifest = "app/src/main/AndroidManifest.xml"
with open(manifest, 'r', encoding='utf-8') as f:
    c = f.read()
old = '<activity android:name=".ui.activity.LxMusicSearchActivity"'
new = old + ' />\n        <activity android:name=".ui.activity.LxArtistDetailActivity"'
if old in c and "LxArtistDetailActivity" not in c:
    c = c.replace(old, new)
    with open(manifest, 'w', encoding='utf-8') as f:
        f.write(c)
    print("LxArtistDetailActivity 已注册")
PYEOF2
fi
if ! grep -q "LxMusicSearchActivity" "$MANIFEST"; then
    python3 << 'PYEOF2'
manifest = "app/src/main/AndroidManifest.xml"
